:root {
  --bg-card: #1a0a00;
  --bg-header: #2e0d00;
  --bg-section-label: #3d1a00;
  --bg-footer: #1f0e00;
  --accent-primary: #ff6b00;
  --accent-secondary: #ffd700;
  --accent-neon: #ff2d6b;
  --text-main: #f5deb3;
  --text-muted: #a07040;
  --text-featured: #ffd700;
  --text-header: #ff6b00;
  --divider: #3d1a00;
  --track-bg: #3d1a00;
  --track-fill: #ff6b00;
  --badge-bg: #3d1a00;
  --badge-special-bg: #ff2d6b;
  --badge-text: #ffd700;
  --badge-special-text: #fff;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

article.jukebox {
  background: var(--bg-card);
  border: 3px solid var(--accent-primary);
  border-radius: 16px;
  width: 480px;
  max-width: 480px;
  overflow: hidden;
  display: flex;
  flex-direction: column;
}

.jukebox-header {
  background: var(--bg-header);
  display: flex;
  flex-direction: row;
  align-items: center;
  justify-content: space-between;
  padding: 10px 18px;
  border-bottom: 2px solid var(--accent-primary);
  gap: 10px;
}

.neon-text {
  font-size: 22px;
  line-height: 1;
}

.header-info {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2px;
}

.diner-name {
  font-size: 22px;
  font-weight: 900;
  color: var(--text-header);
  letter-spacing: 4px;
  line-height: 1;
}

.tagline {
  font-size: 9px;
  font-weight: 700;
  color: var(--accent-secondary);
  letter-spacing: 2px;
}

.menu-grid {
  display: flex;
  flex-direction: row;
  gap: 0;
  padding: 12px 16px;
  flex: 1;
}

.menu-col {
  display: flex;
  flex-direction: column;
  flex: 1;
  gap: 6px;
}

.divider-v {
  width: 2px;
  background: var(--divider);
  border-radius: 2px;
  margin: 0 12px;
  align-self: stretch;
}

.section-label {
  background: var(--bg-section-label);
  color: var(--accent-secondary);
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 2px;
  padding: 3px 8px;
  border-radius: 4px;
  margin-top: 4px;
  border-left: 3px solid var(--accent-neon);
}

.menu-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 3px;
  margin-bottom: 4px;
}

.menu-item {
  display: flex;
  flex-direction: row;
  align-items: baseline;
  gap: 2px;
}

.item-name {
  font-size: 12px;
  font-weight: 600;
  color: var(--text-main);
  white-space: nowrap;
}

.menu-item.featured .item-name {
  color: var(--text-featured);
  font-weight: 800;
}

.item-dots {
  flex: 1;
  border-bottom: 1px dotted var(--text-muted);
  margin: 0 4px;
  margin-bottom: 3px;
}

.item-price {
  font-size: 12px;
  font-weight: 700;
  color: var(--accent-primary);
  white-space: nowrap;
}

.menu-item.featured .item-price {
  color: var(--text-featured);
}

.jukebox-footer {
  background: var(--bg-footer);
  border-top: 2px solid var(--accent-primary);
  padding: 8px 16px 10px;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.now-playing {
  display: flex;
  flex-direction: row;
  align-items: center;
  gap: 8px;
}

.play-icon {
  color: var(--accent-neon);
  font-size: 10px;
  background: var(--bg-section-label);
  border-radius: 50%;
  width: 20px;
  height: 20px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  border: 1px solid var(--accent-neon);
}

.song-title {
  font-size: 11px;
  font-weight: 700;
  color: var(--text-main);
  flex: 1;
}

.song-artist {
  font-size: 10px;
  font-weight: 400;
  color: var(--text-muted);
}

.track-bar {
  height: 4px;
  background: var(--track-bg);
  border-radius: 2px;
  overflow: hidden;
}

.track-fill {
  height: 100%;
  width: 42%;
  background: var(--track-fill);
  border-radius: 2px;
}

.footer-meta {
  display: flex;
  flex-direction: row;
  gap: 6px;
}

.badge {
  background: var(--badge-bg);
  color: var(--badge-text);
  font-size: 8px;
  font-weight: 800;
  letter-spacing: 1.5px;
  padding: 3px 8px;
  border-radius: 20px;
  border: 1px solid var(--accent-primary);
}

.badge.special {
  background: var(--badge-special-bg);
  color: var(--badge-special-text);
  border-color: var(--badge-special-bg);
}
